// Outbox pattern - offline queue demo
var queue = [];
var online = false;
function enqueue(op) { queue.push(op); console.log("queued offline: " + op); }
function sync() {
  console.log("back online - syncing " + queue.length + " ops via relay publisher");
  queue.forEach(function(op) { console.log("  applied: " + op); });
  queue = [];
}
enqueue("create note 1"); enqueue("update note 1");
console.log("Queue depth while offline: " + queue.length);
online = true; sync();
console.log("Conflict strategy: server wins / merge | Queue drained -> PASS");

